const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

// ---------- addresses ----------
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row, key: L + row }
}

// ---------- sheet parsing ----------
const text = fs.readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const addrTok = m[0]
  const content = s.slice(addrTok.length).replace(/^[ \t]+/, '')
  const a = parseAddr(addrTok)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addrTok}\n`)
    process.exit(2)
  }
  if (cells.has(a.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${a.key} is declared twice\n`)
    process.exit(2)
  }
  cells.set(a.key, { col: a.col, row: a.row, key: a.key, content, state: 0, value: null, ast: undefined })
}

// ---------- formula parsing ----------
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[<>=^*\/+\-(),:])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new Error('syntax') }
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-')) { p++; return { k: 'neg', e: unary() } }
    if (isOp('+')) { p++; return { k: 'pos', e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const t = toks[p]
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return e
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            args.push(cmp())
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      const up = t.v.toUpperCase()
      if (up === 'TRUE') return { k: 'bool', v: true }
      if (up === 'FALSE') return { k: 'bool', v: false }
      if (isOp(':')) {
        p++
        if (p < toks.length && toks[p].t === 'word') {
          const w2 = toks[p++].v
          const u2 = w2.toUpperCase()
          if (u2 === 'TRUE' || u2 === 'FALSE' || isOp('(')) fail()
          return { k: 'range', a: t.v, b: w2 }
        }
        fail()
      }
      return { k: 'ref', w: t.v }
    }
    fail()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}

function getAst(cell) {
  if (cell.ast === undefined) cell.ast = cell.content[0] === '=' ? parseFormula(cell.content.slice(1)) : null
  return cell.ast
}

function rangeCells(r) {
  const a = parseAddr(r.a), b = parseAddr(r.b)
  if (!a || !b) return null
  const out = []
  for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
    for (let w = Math.min(a.row, b.row); w <= Math.max(a.row, b.row); w++) out.push({ col: c, row: w })
  return out
}

const colName = (c) => c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(65 + Math.floor((c - 27) / 26)) + String.fromCharCode(65 + ((c - 27) % 26))

// ---------- evaluation ----------
const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ t: 'e', v: e })
const num = (v) => ({ t: 'n', v })

function literal(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (ERRS.includes(content)) return err(content)
  return { t: 's', v: content }
}

function cellValue(col, row) {
  const key = colName(col) + row
  const c = cells.get(key)
  if (!c) return num(0)
  if (c.state === 2) return c.value
  if (c.state === 1) return err('#CYCLE!')
