  let v
  if (c.content[0] === '=') {
    const ast = getAst(c)
    v = ast ? evalNode(ast) : err('#ERR!')
  } else v = literal(c.content)
  c.value = v
  c.state = 2
  return v
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}

function finite(x) { return Number.isFinite(x) ? num(x) : err('#DIV/0!') }

function rank(v) { return v.t === 'n' ? 0 : v.t === 's' ? 1 : 2 }
function cpCompare(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

function evalNode(n) {
  switch (n.k) {
    case 'num': return num(n.v)
    case 'bool': return { t: 'b', v: n.v }
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a.col, a.row) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'neg': case 'pos': {
      const v = evalNode(n.e)
      if (v.t === 'e') return v
      const x = toNum(v)
      if (x.t === 'e') return x
      return n.k === 'neg' ? num(-x.v) : x
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (l.t === 'e') return l
      const r = evalNode(n.r)
      if (r.t === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        let d
        const ra = rank(l), rb = rank(r)
        if (ra !== rb) d = ra - rb
        else if (l.t === 'n') d = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
        else if (l.t === 's') d = cpCompare(l.v, r.v)
        else d = (l.v ? 1 : 0) - (r.v ? 1 : 0)
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { t: 'b', v: res }
      }
      const a = toNum(l)
      if (a.t === 'e') return a
      const b = toNum(r)
      if (b.t === 'e') return b
      switch (n.op) {
        case '+': return finite(a.v + b.v)
        case '-': return finite(a.v - b.v)
        case '*': return finite(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
        case '^': return finite(Math.pow(a.v, b.v))
      }
      return err('#ERR!')
    }
    case 'call': return evalCall(n)
  }
  return err('#ERR!')
}

function evalCall(n) {
  const { name, args } = n
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3 || args.some((a) => a.k === 'range')) return err('#ERR!')
    const c = evalNode(args[0])
    if (c.t === 'e') return c
    let truth
    if (c.t === 'b') truth = c.v
    else if (c.t === 'n') truth = c.v !== 0
    else return err('#VALUE!')
    return evalNode(truth ? args[1] : args[2])
  }
  if (name === 'ABS') {
    if (args.length !== 1 || args[0].k === 'range') return err('#ERR!')
    const v = evalNode(args[0])
    if (v.t === 'e') return v
    const x = toNum(v)
    return x.t === 'e' ? x : num(Math.abs(x.v))
  }
  if (args.length < 1) return err('#ERR!')
  const vals = []
  for (const a of args) {
    if (a.k === 'range') {
      const cs = rangeCells(a)
      if (!cs) return err('#REF!')
      for (const c of cs) vals.push(cellValue(c.col, c.row))
    } else vals.push(evalNode(a))
  }
  const firstErr = vals.find((v) => v.t === 'e')
  if (firstErr) return firstErr
  if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.t === 'e') return x
    nums.push(x.v)
  }
  switch (name) {
    case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return num(Math.min(...nums))
    case 'MAX': return num(Math.max(...nums))
    case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
  }
  return err('#ERR!')
}

// ---------- deps ----------
function collect(n, set) {
  switch (n.k) {
    case 'ref': { const a = parseAddr(n.w); if (a) set.set(a.key, a); break }
    case 'range': {
      const cs = rangeCells(n)
      if (cs) for (const c of cs) set.set(colName(c.col) + c.row, c)
      break
    }
    case 'neg': case 'pos': collect(n.e, set); break
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'call': for (const a of n.args) collect(a, set); break
  }
}

function fmt(v) {
  if (v.t === 'n') return String(Number(v.v.toPrecision(10)))
  if (v.t === 'b') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
for (const c of sorted) {
  if (mode === 'values') {
    out += `${c.key}=${fmt(cellValue(c.col, c.row))}\n`
  } else {
    const set = new Map()
    if (c.content[0] === '=') {
      const ast = getAst(c)
      if (ast) collect(ast, set)
    }
    const ds = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out += `${c.key}:${ds.map((d) => ' ' + colName(d.col) + d.row).join('')}\n`
  }
}
process.stdout.write(out)
"}

